      "scss": "/* CLASE PROPIA */\n\n.ronin-button {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 0.5rem;\n\n  border: none;\n  cursor: pointer;\n\n  border-radius: var(--radius-md);\n\n  font-weight: 600;\n\n  transition:\n    background-color 0.2s ease,\n    color 0.2s ease,\n    border-color 0.2s ease,\n    transform 0.2s ease;\n}\n\n/* TAMAÑOS */\n\n.sm {\n  padding: 0.5rem 1rem;\n  font-size: 0.8rem;\n}\n\n.md {\n  padding: 0.75rem 1.5rem;\n  font-size: 0.95rem;\n}\n\n.lg {\n  padding: 1rem 2rem;\n  font-size: 1.1rem;\n}\n\n/* PRIMARY */\n\n.primary {\n  background: var(--color-bg-contrast);\n  color: var(--color-text-contrast);\n}\n\n.primary:hover:not(:disabled) {\n  background: var(--color-primary-hover);\n}\n\n/* SECONDARY */\n\n.secondary {\n  background: var(--color-surface);\n  color: var(--color-text);\n  border: 1px solid var(--color-border);\n}\n\n.secondary:hover:not(:disabled) {\n  background: var(--color-surface-hover);\n}\n\n/* OUTLINE */\n\n.outline {\n  background: transparent;\n  color: var(--color-primary);\n  border: 1px solid var(--color-primary);\n}\n\n.outline:hover:not(:disabled) {\n  background: rgba(255, 145, 0, 0.1);\n}\n\n/* GHOST */\n\n.ghost {\n  background: transparent;\n  color: var(--color-text);\n}\n\n.ghost:hover:not(:disabled) {\n  background: var(--color-surface-hover);\n}\n\n/* DANGER */\n\n.danger {\n  background: var(--color-danger);\n  color: white;\n}\n\n.danger:hover:not(:disabled) {\n  filter: brightness(1.1);\n  box-shadow: 0px 0px 6px var(--color-danger);\n  scale: 1.05;\n}\n\n/* OTROS */\n\n.full-width {\n  width: 100%;\n}\n\n.rounded {\n  border-radius: 999px;\n}\n\n.loading {\n  pointer-events: none;\n}\n\n.ronin-button:disabled {\n  opacity: 0.5;\n  cursor: not-allowed;\n}\n\n/* SPINNER */\n\n.spinner {\n  width: 1rem;\n  height: 1rem;\n\n  border: 2px solid rgba(255, 255, 255, 0.3);\n\n  border-top-color: white;\n\n  border-radius: 50%;\n\n  animation: spin 0.8s linear infinite;\n}\n\n@keyframes spin {\n  to {\n    transform: rotate(360deg);\n  }\n}\n\n/* CLOSE BUTTON */\n\n.close {\n  width: 40px;\n  height: 40px;\n\n  padding: 0;\n\n  background: transparent;\n\n  color: var(--color-text-muted);\n\n  border-radius: 50%;\n}\n\n.close i {\n  transition: all 0.3s ease;\n}\n\n.close:hover:not(:disabled) {\n  background: rgba(221, 250, 217, 0.15);\n\n  color: var(--color-success);\n  font-size: 1.2rem;\n\n  box-shadow: 0 0 12px rgba(88, 239, 68, 0.3);\n\n  transform: rotate(90deg) scale(1.05);\n}\n\n/* CLOSE MORPH */\n\n.close-morph {\n  width: 40px;\n  height: 40px;\n\n  padding: 0;\n\n  background: transparent;\n\n  color: var(--color-text-muted);\n\n  border-radius: 50%;\n}\n\n.close-morph i {\n  transition: all 0.3s ease;\n}\n\n.close-morph:hover:not(:disabled) {\n  background: var(--color-danger);\n\n  color: white;\n  font-size: 1.2rem;\n\n  box-shadow: 0 0 20px rgba(239, 68, 68, 0.5);\n\n  transform: scale(1.15) rotate(180deg);\n}\n\n/* ICON BUTTON */\n\n.icon {\n  width: 44px;\n  height: 44px;\n\n  padding: 0;\n\n  display: flex;\n  align-items: center;\n  justify-content: center;\n\n  background: var(--color-surface);\n\n  border: 1px solid var(--color-border);\n\n  border-radius: 50%;\n\n  color: var(--color-text);\n\n  font-size: 1.1rem;\n\n  box-shadow: var(--shadow-sm);\n}\n\n.icon i {\n  transition: all 0.2s ease;\n  color: inherit;\n}\n\n.icon:hover:not(:disabled) {\n  transform: translateY(-2px) scale(1.05);\n}\n\n.icon-primary:hover {\n  border-color: var(--color-primary);\n\n  box-shadow: 0 0 12px rgba(255, 145, 0, 0.4);\n\n  color: var(--color-primary);\n}\n\n.icon-danger:hover {\n  border-color: var(--color-danger);\n\n  box-shadow: 0 0 12px rgba(239, 68, 68, 0.4);\n\n  color: var(--color-danger);\n}\n\n.icon-success:hover {\n  border-color: var(--color-success);\n\n  box-shadow: 0 0 12px rgba(34, 197, 94, 0.4);\n\n  color: var(--color-success);\n}\n\n/* ANIMATED BUTTON */\n\n.animated-pulse {\n  position: relative;\n\n  overflow: hidden;\n\n  background: var(--color-surface);\n\n  color: white;\n\n  border: 1px solid rgba(251, 255, 0, 0.438);\n}\n\n.animated-pulse .animated-border {\n  position: absolute;\n\n  inset: 0;\n\n  border-radius: inherit;\n\n  border: 2px solid var(--color-primary);\n\n  animation: pulseBorder 2s infinite;\n}\n\n.animated-pulse:hover {\n  box-shadow: 0 0 20px rgba(255, 238, 0, 0.3);\n}\n\n@keyframes pulseBorder {\n  0% {\n    opacity: 0.3;\n    transform: scale(1);\n  }\n\n  50% {\n    opacity: 1;\n    transform: scale(1.04);\n  }\n\n  100% {\n    opacity: 0.3;\n    transform: scale(1);\n  }\n}\n\n.animated-neon {\n  position: relative;\n\n  overflow: hidden;\n\n  background: var(--color-surface);\n\n  color: white;\n}\n\n.animated-neon::before {\n  content: '';\n\n  position: absolute;\n\n  top: 0;\n  left: -100%;\n\n  width: 100%;\n  height: 100%;\n\n  background: linear-gradient(90deg, transparent, rgba(251, 255, 0, 0.8), transparent);\n\n  animation: neonFlow 2.5s linear infinite;\n}\n\n.animated-neon:hover {\n  box-shadow: 0 0 20px rgba(255, 238, 0, 0.3);\n}\n\n@keyframes neonFlow {\n  from {\n    left: -100%;\n  }\n\n  to {\n    left: 100%;\n  }\n}\n\n.animated-energy {\n  position: relative;\n\n  overflow: hidden;\n\n  background: var(--color-surface);\n\n  color: white;\n}\n\n.animated-energy::before {\n  content: '';\n\n  position: absolute;\n\n  inset: -200%;\n\n  border-radius: inherit;\n\n  background: conic-gradient(\n    from 0deg,\n    transparent,\n    var(--color-primary),\n    transparent,\n    var(--color-primary),\n    transparent\n  );\n\n  animation: energySpin 3s linear infinite;\n}\n\n.animated-energy::after {\n  content: '';\n\n  position: absolute;\n\n  inset: 2px;\n\n  background: var(--color-surface);\n\n  border-radius: inherit;\n}\n\n.animated-energy .button-content {\n  position: relative;\n  z-index: 1;\n}\n\n.animated-energy:hover {\n  box-shadow: 0 0 30px rgba(255, 238, 0, 0.3);\n}\n\n@keyframes energySpin {\n  from {\n    transform: rotate(0deg);\n  }\n\n  to {\n    transform: rotate(360deg);\n  }\n}\n\n/* CTA */\n\n.cta {\n  background: var(--color-primary, #ff9100);\n  color: var(--color-text-contrast, #1f1f1f);\n  border: 1px solid transparent;\n  box-shadow: 0 4px 18px #ff910026;\n}\n\n.cta:hover:not(:disabled) {\n  background: var(--color-primary-hover, #ca7609);\n  transform: translateY(-2px);\n}\n\n.cta:active:not(:disabled) {\n  transform: translateY(0);\n}\n\n.cta:focus-visible {\n  outline: 2px solid var(--color-primary, #ff9100);\n  outline-offset: 4px;\n}\n",
      "ts": "import { Component, computed, input } from '@angular/core';\n\nexport type ButtonVariant =\n  | 'primary'\n  | 'secondary'\n  | 'outline'\n  | 'ghost'\n  | 'danger'\n  | 'close'\n  | 'close-morph'\n  | 'icon'\n  | 'animated-pulse'\n  | 'animated-neon'\n  | 'animated-energy'\n  | 'cta'\n  | 'link'\n  | 'troll';\n\nexport type ButtonSize = 'sm' | 'md' | 'lg';\n\nexport type IconColor = 'default' | 'primary' | 'success' | 'danger';\n\n@Component({\n  selector: 'ui-button',\n  templateUrl: './button.html',\n  styleUrl: './button.scss',\n})\nexport class ButtonComponent {\n  readonly variant = input<ButtonVariant>('primary');\n\n  readonly size = input<ButtonSize>('md');\n\n  readonly disabled = input(false);\n\n  readonly loading = input(false);\n\n  readonly fullWidth = input(false);\n\n  readonly rounded = input(false);\n\n  readonly colorScheme = input<IconColor>('default');\n\n  readonly classes = computed(() =>\n    [\n      'ronin-button',\n      this.variant(),\n      this.size(),\n      this.fullWidth() ? 'full-width' : '',\n      this.rounded() ? 'rounded' : '',\n      this.loading() ? 'loading' : '',\n      this.disabled() ? 'disabled' : '',\n      this.colorScheme() !== 'default' ? `icon-${this.colorScheme()}` : '',\n    ]\n      .filter(Boolean)\n      .join(' '),\n  );\n}\n"
