    "files": {
      "html": "<div class=\"input-wrapper\">\n  @if (variant() === 'floating') {\n    <div class=\"floating-wrapper\">\n      <input\n        [id]=\"inputId\"\n        [attr.aria-label]=\"label() || placeholder()\"\n        class=\"ronin-input floating\"\n        [class.success]=\"state() === 'success'\"\n        [class.error]=\"state() === 'error'\"\n        [placeholder]=\"' '\"\n        [disabled]=\"disabled()\"\n      />\n\n      <label [for]=\"inputId\">\n        {{ label() }}\n      </label>\n    </div>\n  } @else {\n    @if (variant() === 'search') {\n      <i class=\"ri-search-line input-icon\"></i>\n    }\n\n    <input\n      [id]=\"inputId\"\n      [attr.aria-label]=\"label() || placeholder()\"\n      [type]=\"variant() === 'password' ? (showPassword() ? 'text' : 'password') : 'text'\"\n      [class]=\"classes()\"\n      [placeholder]=\"placeholder()\"\n      [disabled]=\"disabled()\"\n    />\n\n    @if (state() === 'success') {\n      <i class=\"ri-check-line status-icon success-icon\"></i>\n    }\n\n    @if (state() === 'error') {\n      <i class=\"ri-error-warning-line status-icon error-icon\"></i>\n    }\n\n    @if (variant() === 'password') {\n      <button\n        class=\"input-action\"\n        [attr.aria-label]=\"showPassword() ? 'Ocultar contraseña' : 'Mostrar contraseña'\"\n        type=\"button\"\n        (click)=\"togglePassword()\"\n      >\n        @if (showPassword()) {\n          <i class=\"ri-eye-off-line\"></i>\n        } @else {\n          <i class=\"ri-eye-line\"></i>\n        }\n      </button>\n    }\n  }\n</div>\n",
      "scss": ".input-wrapper {\n  position: relative;\n\n  width: fit-content;\n}\n\n.ronin-input {\n  width: 320px;\n\n  height: 48px;\n\n  padding: 0 1rem;\n\n  border: 1px solid var(--color-border);\n\n  border-radius: 12px;\n\n  background: transparent;\n\n  color: var(--color-text);\n\n  font-size: 0.95rem;\n\n  outline: none;\n\n  transition: all 0.25s ease;\n}\n\n.ronin-input::placeholder {\n  color: var(--color-text-muted);\n}\n\n.ronin-input:hover:not(:disabled) {\n  border-color: rgba(255, 145, 0, 0.4);\n}\n\n.ronin-input:focus {\n  border-color: var(--color-primary);\n\n  box-shadow:\n    0 0 0 2px rgba(255, 145, 0, 0.15),\n    0 0 15px rgba(255, 145, 0, 0.15);\n}\n\n/* FILLED */\n\n.filled {\n  background: var(--color-surface);\n\n  border: 2px solid rgba(255, 145, 0, 0.4);\n\n  color: #ffffff;\n\n  font-weight: 500;\n}\n\n.filled::placeholder {\n  color: var(--color-text-muted);\n}\n\n.filled:hover:not(:disabled) {\n  border-color: var(--color-primary);\n\n  box-shadow: 0 0 15px rgba(255, 145, 0, 0.15);\n}\n\n.filled:focus {\n  border-width: 2px;\n\n  border-color: var(--color-primary);\n\n  box-shadow:\n    0 0 0 3px rgba(255, 145, 0, 0.15),\n    0 0 25px rgba(255, 145, 0, 0.25);\n}\n\n/* SEARCH */\n\n.search {\n  padding-left: 3rem;\n  background: var(--color-surface);\n}\n\n.input-icon {\n  position: absolute;\n\n  left: 1rem;\n  top: 50%;\n\n  transform: translateY(-50%);\n\n  color: var(--color-text-muted);\n\n  font-size: 1rem;\n  transition: all 0.25s ease;\n  pointer-events: none;\n}\n\n.input-wrapper:hover .input-icon {\n  color: var(--color-primary);\n\n  filter: drop-shadow(0 0 8px rgba(255, 145, 0, 0.5));\n}\n\n.input-wrapper:has(.search:focus) .input-icon {\n  color: var(--color-primary);\n\n  filter: drop-shadow(0 0 10px rgba(255, 145, 0, 0.8));\n}\n\n/* DISABLED */\n\n.ronin-input:disabled {\n  opacity: 0.5;\n\n  cursor: not-allowed;\n}\n\n/* PASSWORD */\n\n.password {\n  padding-right: 3rem;\n}\n\n/* ACTION */\n\n.input-action {\n  position: absolute;\n\n  top: 50%;\n  right: 0.75rem;\n\n  transform: translateY(-50%);\n\n  display: flex;\n  align-items: center;\n  justify-content: center;\n\n  width: 32px;\n  height: 32px;\n\n  border: none;\n\n  background: transparent;\n\n  color: var(--color-text-muted);\n\n  cursor: pointer;\n\n  transition: var(--transition);\n}\n\n/* SUCCESS AND ERROR */\n\n.input-action:hover {\n  color: var(--color-primary);\n}\n\n.success {\n  border-color: var(--color-success);\n  padding-right: 3rem;\n}\n\n.success:focus {\n  box-shadow:\n    0 0 0 3px rgba(34, 197, 94, 0.15),\n    0 0 15px rgba(34, 197, 94, 0.2);\n}\n\n.error {\n  border-color: var(--color-danger);\n  padding-right: 3rem;\n}\n\n.error:focus {\n  box-shadow:\n    0 0 0 3px rgba(239, 68, 68, 0.15),\n    0 0 15px rgba(239, 68, 68, 0.2);\n}\n\n.status-icon {\n  position: absolute;\n\n  right: 1rem;\n  top: 50%;\n\n  transform: translateY(-50%);\n\n  font-size: 1rem;\n\n  pointer-events: none;\n}\n\n.success-icon {\n  color: var(--color-success);\n  filter: drop-shadow(0 0 4px rgba(34, 197, 94, 0.5));\n}\n\n.error-icon {\n  color: var(--color-danger);\n  filter: drop-shadow(0 0 4px rgba(239, 68, 68, 0.5));\n}\n\n/* FLOATING */\n\n.floating-wrapper {\n  position: relative;\n\n  width: 320px;\n}\n\n.floating {\n  width: 100%;\n}\n\n.floating-wrapper label {\n  position: absolute;\n\n  left: 1rem;\n  top: 50%;\n\n  transform: translateY(-50%);\n\n  background: var(--color-bg);\n\n  padding: 0 0.4rem;\n\n  color: var(--color-text-muted);\n\n  transition: all 0.2s ease;\n\n  pointer-events: none;\n}\n\n.floating:focus + label,\n.floating:not(:placeholder-shown) + label {\n  top: 0;\n\n  font-size: 0.8rem;\n\n  color: var(--color-primary);\n}\n",
      "ts": "import { Component, computed, input, signal } from '@angular/core';\n\nexport type InputVariant = 'default' | 'filled' | 'search' | 'password' | 'floating';\n\nexport type InputState = 'default' | 'success' | 'error';\n\nlet nextInputId = 0;\n\n@Component({\n  selector: 'ui-input',\n  templateUrl: './input.html',\n  styleUrl: './input.scss',\n})\nexport class InputComponent {\n  readonly inputId = `ronin-input-${nextInputId++}`;\n\n  readonly placeholder = input('Enter text...');\n  readonly variant = input<InputVariant>('default');\n  readonly disabled = input(false);\n  readonly label = input('');\n  readonly state = input<InputState>('default');\n  readonly showPassword = signal(false);\n  readonly classes = computed(() =>\n    ['ronin-input', this.variant(), this.state()].filter(Boolean).join(' '),\n  );\n\n  togglePassword(): void {\n    this.showPassword.update((value) => !value);\n  }\n}\n"
    }
