      "scss": ":host {\n  display: block;\n  max-width: 100%;\n  color: #e4e5df;\n}\n.chip {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  padding: 13px 14px 13px 18px;\n  border: 1px solid #ffffff20;\n  background: #101716;\n  border-radius: 10px;\n}\ncode {\n  font: 11px monospace;\n  overflow-wrap: anywhere;\n  user-select: all;\n}\nbutton {\n  flex-shrink: 0;\n  display: grid;\n  place-items: center;\n  padding: 8px;\n  border: 1px solid #ffffff14;\n  border-radius: 6px;\n  background: #ffffff08;\n  color: #c4d8b2;\n  cursor: pointer;\n}\nbutton:hover {\n  background: #ffffff16;\n}\nbutton:focus-visible {\n  outline: 2px solid #c4d8b2;\n  outline-offset: 3px;\n}\n.feedback {\n  display: block;\n  min-height: 12px;\n  margin-top: 14px;\n  text-align: center;\n  color: #8c9a8d;\n  font: 8px monospace;\n  letter-spacing: 0.07em;\n}\n",
      "ts": "import { Component, input, signal } from '@angular/core';\n\n@Component({\n  selector: 'ui-copy-chip',\n  standalone: true,\n  templateUrl: './copy-chip.html',\n  styleUrl: './copy-chip.scss',\n})\nexport class CopyChipComponent {\n  readonly text = input('npm install @angular/core');\n  readonly message = signal('');\n  async copy(): Promise<void> {\n    try {\n      await navigator.clipboard.writeText(this.text());\n      this.message.set('Copiado');\n    } catch {\n      this.message.set('Selecciona el texto para copiarlo');\n    }\n  }\n}\n"
